/* 同一订单里每个种类的颜色必须不同：新增取未用色；加载/导出前自动修复重复 */
function hsl2hex(h,sat,l){sat/=100;l/=100;const k=n=>(n+h/30)%12,a=sat*Math.min(l,1-l),f=n=>l-a*Math.max(-1,Math.min(k(n)-3,Math.min(9-k(n),1)));return"#"+[f(0),f(8),f(4)].map(x=>Math.round(x*255).toString(16).padStart(2,"0")).join("")}
function extraColor(used){for(let i=0;i<400;i++){const c=hsl2hex((i*137.5+20)%360,58+(i%3)*8,46+(i%4)*3);if(!used.has(c))return c}return COLORS[0]}
function freeColor(used){return COLORS.find(x=>!used.has(x))||extraColor(used)}
function pickColor(o){return freeColor(new Set(o.cats.map(c=>c.color)))}
function ensureColors(o){let ch=false;const seen=new Set();o.cats.forEach((c,i)=>{if(!c.color||seen.has(c.color)){const later=new Set(o.cats.slice(i+1).map(d=>d.color));c.color=freeColor(new Set([...seen,...later]));ch=true}seen.add(c.color)});return ch}
