function unitTr(u,lang,n){if(lang!="es"||!u)return u;const e=UES[u];return e?(n==1?e[0]:e[1]):u}
function unitSums(o,items){const m=new Map();items.forEach(it=>{if(it.q>0){const u=unitOf(o,it);m.set(u,(m.get(u)||0)+it.q)}});return m}
function totTxt(o,lang){const m=unitSums(o,o.cats.flatMap(c=>c.items));return[...m].map(([u,n])=>n+" "+(u?unitTr(u,lang,n):(lang=="zh"?"件":"un"))).join(" + ")||"0"}
