/* ---------- 名称处理 / 品名库 ---------- */
function tcName(s){s=String(s).replace(/\s+/g," ").trim();if(!s)return s;
 if(s===s.toUpperCase()&&s!==s.toLowerCase()){const small=new Set(["y","de","del","la","el","en","con","e","o","a","las","los"]);return s.toLowerCase().split(" ").map((w,i)=>(i&&small.has(w))?w:w.charAt(0).toUpperCase()+w.slice(1)).join(" ")}
 return s.charAt(0).toUpperCase()+s.slice(1)}
function vocAll(){const out=[],seen=new Set();if(typeof SRCS!="undefined")SRCS.list.forEach(x=>{const d=srcData(x.id);if(d)Object.values(d.cats).forEach(l=>l.forEach(it=>{const k=norm(it[0]);if(!seen.has(k)){seen.add(k);out.push(it[0])}}))});(S.vocab||[]).forEach(v=>{const k=norm(v);if(!seen.has(k)){seen.add(k);out.push(v)}});return out}
function vocabFind(n){const k=norm(n);return vocAll().find(v=>norm(v)==k)||null}
function fixName(s){s=tcName(s);if(!s)return s;const k=skey(s);if(typeof SRCS!="undefined"){for(const x of SRCS.list){const d=srcData(x.id);if(!d)continue;for(const l of Object.values(d.cats))for(const it of l)if(skey(it[0])==k)return it[0]}}return vocabFind(s)||s}
/* 品名库去重：和 Saphirus 源重复（忽略大小写/重音/空格）的以 Saphirus 源为准，从品名库移除；品名库内部同名也只留一条 */
function vocDedupe(){if(!S||!S.vocab)return 0;const ss=vocSrcSet(),seen=new Set(),before=S.vocab.length;
 S.vocab=S.vocab.filter(v=>{const k=skey(v);if(!k||ss.has(k)||seen.has(k))return false;seen.add(k);return true});
 const n=before-S.vocab.length;if(n){try{localStorage.setItem("pedidos_vocab_bak",JSON.stringify({t:Date.now(),n}))}catch(e){}}return n}
function addVocab(n){const k=norm(n);if(!k)return;if(!vocabFind(n))S.vocab.push(n)}   /* vocabFind 已含 Saphirus 源：源里有的不再写进品名库 */
function lev(a,b){const m=a.length,n=b.length;if(Math.abs(m-n)>2)return 9;let p=[...Array(n+1).keys()];for(let i=1;i<=m;i++){const c=[i];for(let j=1;j<=n;j++)c[j]=Math.min(p[j]+1,c[j-1]+1,p[j-1]+(a[i-1]==b[j-1]?0:1));p=c}return p[n]}
function fuzzy(n,lim){const k=norm(n);if(k.length<4)return[];const r=[];vocAll().forEach(v=>{const kv=norm(v);if(kv==k)return;const d=lev(k,kv);if(d<=(k.length<=5?1:2))r.push([d,v])});r.sort((a,b)=>a[0]-b[0]);return r.slice(0,lim||3).map(x=>x[1])}

