/* ---------- 存取 ---------- */
function fix(s){
 if(!s||!Array.isArray(s.orders))return null;
 s.vocab=Array.isArray(s.vocab)?s.vocab.filter(v=>typeof v=="string"&&v.trim()):null;
 s.del=(s.del&&typeof s.del=="object")?s.del:{};
 s.orders.forEach(o=>{o.id=o.id||uid();o.upd=o.upd||0;o.sup=o.sup||"";o.dt=o.dt||"";
  o.status=STAT[o.status]?o.status:"draft";o.sort=["manual","az","qty","new"].includes(o.sort)?o.sort:"manual";
  o.unit=String(o.unit||"").trim().slice(0,8);o.price=!!o.price;o.dk=o.dk?1:0;o.cur=o.cur||"$";o.lang=o.lang=="zh"?"zh":"es";o.theme=(o.theme>=0&&o.theme<THEMES.length)?(o.theme|0):0;
  o.cats=(o.cats||[]).map((c,i)=>({name:c.name||"",sub:c.sub||"",color:c.color||COLORS[i%COLORS.length],items:(c.items||[]).map(it=>Array.isArray(it)?{n:String(it[0]),q:parseInt(it[1])||0,p:null}:{n:String(it.n||""),id:it.id||(it.n?undefined:uid()),q:Math.max(0,parseInt(it.q)||0),u:String(it.u||"").trim().slice(0,8),p:(it.p==null||it.p==="")?null:Math.max(0,parseFloat(it.p)||0)})}))});
 if(!s.vocab){const m=new Map();s.orders.forEach(o=>o.cats.forEach(c=>c.items.forEach(i=>{const k=norm(i.n);if(k&&!m.has(k))m.set(k,i.n)})));s.vocab=[...m.values()]}

 if(!s.uses||typeof s.uses!="object"||Array.isArray(s.uses)){const u={};s.orders.forEach(o=>o.cats.forEach(cc=>cc.items.forEach(i=>{const k=norm(i.n).replace(/\s*&\s*/g," y ").replace(/\s+/g," ").trim();if(!k)return;const e=u[k]||(u[k]=[0,0]);e[0]++;e[1]=Math.max(e[1],o.upd||0)})));s.uses=u}
 s.orders.forEach(ensureColors);
 return s}
function loadLocal(){
 for(const k of [KEY,KEY1]){try{const s=fix(JSON.parse(localStorage.getItem(k)));if(s)return s}catch(e){}}
 try{const old=JSON.parse(localStorage.getItem(OLD));if(old&&old.cats){return fix({orders:[{id:uid(),sup:old.sup||"",dt:old.dt||today(),upd:Date.now(),cats:old.cats}]})}}catch(e){}
 return fix({orders:[sample()]});
}
function lsSave(){try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){toast("⚠ 浏览器存储失败，请导出备份")}}
function save(){lsSave();if(SERVER){pending=true;clearTimeout(pushT);pushT=setTimeout(push,300)}}
function merge(j){
 S.del=Object.assign({},j.del,S.del);
 const map=new Map();[...j.orders,...S.orders].forEach(o=>{const e=map.get(o.id);if(!e||(o.upd||0)>=(e.upd||0))map.set(o.id,o)});
 S.orders=[...map.values()].filter(o=>!(S.del[o.id]&&S.del[o.id]>=(o.upd||0)));
 S.uses=S.uses||{};Object.entries(j.uses||{}).forEach(([k,v])=>{const e=S.uses[k];if(!e||(v[1]||0)>(e[1]||0))S.uses[k]=v});
 const have=new Set(S.vocab.map(norm));(j.vocab||[]).forEach(v=>{if(!have.has(norm(v))){S.vocab.push(v);have.add(norm(v))}});
}
function push(){
 pending=false;if(pushing){dirty=true;return}pushing=true;
 fetch("api/data",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.assign({},S,{rev:REV}))})
 .then(async r=>{
  if(r.status==409){const j=fix(await r.json());merge(j);REV=j.rev||0;lsSave();pushing=false;rerender();push();return}
  if(!r.ok)throw 0;const j=await r.json();REV=j.rev;pushing=false;if(dirty){dirty=false;push()}})
 .catch(()=>{pushing=false;toast("⚠ 写入本地文件失败")});
}
async function poll(){
 if(!SERVER||document.hidden||pushing||pending||MOPEN||isTyping())return;
 try{const r=await fetch("api/data",{cache:"no-store"});if(!r.ok)return;const j=fix(await r.json());
  if(j.fresh||(j.rev||0)===REV)return;
  if(pending||pushing)return;merge(j);REV=j.rev||0;lsSave();rerender();toast("已同步另一台设备的修改")}catch(e){}
}
function rerender(){if(MOPEN||isTyping())return;route(true)}
async function boot(){
 S=loadLocal();{const n=vocDedupe();if(n){lsSave();setTimeout(()=>toast("品名库与商品源重复的 "+n+" 条已去重（以商品源写法为准）"),800)}}route();
 try{const r=await fetch("api/data",{cache:"no-store"});
  if(r.ok){const j=fix(await r.json());SERVER=true;
   if(j.fresh){REV=0;push()}else{REV=j.rev||0;S=j;if(vocDedupe()){lsSave();save()}else lsSave()}
   route();setInterval(poll,4000)}}catch(e){}
}

