 {const nv=o?"e":"h";if(route._v&&route._v!==nv){const el=$(o?"vEdit":"vHome");el.classList.remove("vin");void el.offsetWidth;el.classList.add("vin");if(typeof LENS_REL=="function")LENS_REL()}route._v=nv}
