/* ---------- 撤销 / 重做（每个订单独立） ---------- */
const HS={};
const snap=o=>{const c=JSON.parse(JSON.stringify(o));delete c.upd;return JSON.stringify(c)};
const hist=o=>HS[o.id]||(HS[o.id]={u:[],r:[],tag:"",t:0});
function mut(fn,tag,noRender){
 const o=cur();if(!o)return;const h=hist(o),before=snap(o);fn(o);
 if(snap(o)==before)return;
 const now=Date.now();
 if(!(tag&&h.tag===tag&&now-h.t<1500)){h.u.push(before);if(h.u.length>100)h.u.shift()}
 h.tag=tag||"";h.t=now;h.r=[];o.upd=now;save();
 if(!noRender)renderEdit();else syncUndo();
}
function restore(o,s){const c=JSON.parse(s);Object.keys(o).forEach(k=>{if(k!="id")delete o[k]});Object.assign(o,c);o.upd=Date.now();save();renderEdit()}
function undo(){const o=cur();if(!o)return;FX("tick");const h=hist(o);if(!h.u.length)return;h.r.push(snap(o));h.tag="";restore(o,h.u.pop())}
function redo(){const o=cur();if(!o)return;FX("tick");const h=hist(o);if(!h.r.length)return;h.u.push(snap(o));h.tag="";restore(o,h.r.pop())}
function syncUndo(){const o=cur();if(!o)return;const h=hist(o);$("bUndo").disabled=!h.u.length;$("bRedo").disabled=!h.r.length}
addEventListener("keydown",e=>{if(!(e.ctrlKey||e.metaKey)||e.key.toLowerCase()!="z"||isTyping()||!cur())return;e.preventDefault();e.shiftKey?redo():undo()});

