 SG[ci]=vocAll().filter(x=>{const kx=norm(x);return kx.includes(k)&&kx!=k&&!have.has(kx)}).sort((a,b)=>(norm(a).startsWith(k)?0:1)-(norm(b).startsWith(k)?0:1)||a.length-b.length).slice(0,6);
